31	/**
32	*	결제	명령	서비스
33	*	결제	요청	처리,	환불	등	결제	관련	명령을	처리
34	*/
35	@Service
36	@RequiredArgsConstructor
37	@Transactional
38	@Slf4j
39	public	class	PaymentCommandService	{
40
41	private	final	PaymentRepository	paymentRepository;
42	private	final	PaymentInfoQueryService	paymentInfoQueryService;
43	private	final	PortOneApiClient	portOneApiClient;
44	private	final	NotificationCommandService	notificationCommandService;
45	private	final	SaleBidQueryService	saleBidQueryService;
46
47	/**
48	*	결제	처리
49	*	결제	유형에	따라	적절한	결제	처리	로직	수행
50	*
51	*	@param	order	결제	대상	주문
52	*	@param	user	결제	요청	사용자
53	*	@param	requestDto	결제	요청	정보
54	*	@return	생성된	결제	정보
55	*	@throws	PaymentException	결제	처리	실패	시
56	*/
57	public	Payment	processPayment(Order	order,	User	user,	PaymentRequestDto	requestDto)	{
58	Instant	start	=	Instant.now();
59	try	{
60	validatePaymentRequest(order,	user,	requestDto);
61
62	log.info("결제	처리	시작:	주문ID={},	사용자={},	결제유형={}",
63	order.getId(),	user.getEmail(),	requestDto.getResolvedPaymentType());
64
65	Payment	payment;
66
67	switch	(requestDto.getResolvedPaymentType())	{
68	case	"CARD":
69	payment	=	createCardPayment(order,	user,	(CardPaymentRequestDto)	requestDto);
70	break;
71	case	"ACCOUNT":
72	payment	=	createAccountPayment(order,	user,	(AccountPaymentRequestDto)	requestDto);
73	break;
74	case	"GENERAL":
75	payment	=	createGeneralPayment(order,	user,	(GeneralPaymentRequestDto)	requestDto);
76	break;
77	default:
78	throw	new	PaymentException(PaymentErrorCode.PAYMENT_VALIDATION_FAILED,
79	"유효하지	않은	결제	유형:	"	+	requestDto.getPaymentType());
80	}
81
82	//	알림	전송	및	Sale	상태	업데이트
83	notifyUsersAndUpdateSaleStatus(order,	payment);
84
85	log.info("결제	처리	완료:	주문ID={},	결제ID={},	상태={}",
86	order.getId(),	payment.getId(),	payment.getStatus());
87
88	return	payment;
89	}	catch	(PaymentException	e)	{
90	log.error("결제	처리	실패:	주문ID={},	사용자={},	에러코드={},	메시지={}",
91	order	!=	null	?	order.getId()	:	"null",
92	user	!=	null	?	user.getEmail()	:	"null",
93	e.getErrorCode().getCode(),	e.getMessage());
94	throw	e;	//	이미	PaymentException이면	그대로	전파
95	}	catch	(Exception	e)	{
96	log.error("결제	처리	중	예상치	못한	오류	발생:	주문ID={},	사용자={},	오류={}",
97	order	!=	null	?	order.getId()	:	"null",
98	user	!=	null	?	user.getEmail()	:	"null",
99	e.getMessage(),	e);
100	throw	new	PaymentProcessingException("결제	처리	중	오류가	발생했습니다:	"	+	e.getMessage());
101	}	finally	{
102	//	처리	시간	로깅
103	Instant	end	=	Instant.now();
104	Duration	duration	=	Duration.between(start,	end);
105	log.debug("결제	처리	총	소요	시간:	{}ms",	duration.toMillis());
106	}
107	}
108
109	/**
110	*	결제	요청	검증
111	*
112	*	@param	order	주문	정보
113	*	@param	user	사용자	정보
114	*	@param	requestDto	결제	요청	DTO
115	*	@throws	PaymentException	검증	실패	시
116	*/
117	private	void	validatePaymentRequest(Order	order,	User	user,	PaymentRequestDto	requestDto)	{
118	if	(order	==	null)	{
119	throw	new	PaymentException(PaymentErrorCode.PAYMENT_PROCESSING_FAILED,	"주문	정보가	없습니다.");
120	}
121
122	if	(user	==	null)	{
123	throw	new	PaymentException(PaymentErrorCode.PAYMENT_PROCESSING_FAILED,	"사용자	정보가	없습니다.");
124	}
125
126	if	(requestDto	==	null)	{
127	throw	new	PaymentException(PaymentErrorCode.PAYMENT_VALIDATION_FAILED,	"결제	요청	정보가	없습니다.");
128	}
129
130	//	주문	ID와	사용자	이메일이	일치하는지	확인
131	if	(!order.getId().equals(requestDto.getOrderId()))	{
132	throw	new	PaymentException(PaymentErrorCode.PAYMENT_VALIDATION_FAILED,
133	"주문	ID가	일치하지	않습니다.	요청ID:	"	+	requestDto.getOrderId()	+	",	실제ID:	"	+	order.getId());
134	}
135
136	if	(!user.getEmail().equals(requestDto.getUserEmail()))	{
137	throw	new	PaymentException(PaymentErrorCode.PAYMENT_VALIDATION_FAILED,
138	"사용자	이메일이	일치하지	않습니다.	요청이메일:	"	+	requestDto.getUserEmail()	+	",	실제이메일:	"	+	user.getEmail());
139	}
140
141	//	결제	금액	검증
142	if	(requestDto.getPaidAmount()	<=	0)	{
143	throw	new	PaymentException(PaymentErrorCode.INVALID_PAYMENT_AMOUNT,
144	"결제	금액은	0보다	커야	합니다.	금액:	"	+	requestDto.getPaidAmount());
145	}
146	}
147
148	/**
149	*	카드	결제	생성
150	*
151	*	@param	order	주문	정보
152	*	@param	user	사용자	정보
153	*	@param	requestDto	카드	결제	요청	DTO
154	*	@return	생성된	카드	결제	정보
155	*	@throws	PaymentException	결제	처리	실패	시
156	*/
157	private	Payment	createCardPayment(Order	order,	User	user,	CardPaymentRequestDto	requestDto)	{
158	Instant	start	=	Instant.now();
159	try	{
160	log.info("카드	결제	처리	시작:	주문ID={},	결제정보ID={}",
161	order.getId(),	requestDto.getPaymentInfoId());
162
163	//	1.	PaymentInfo	조회
164	PaymentInfo	paymentInfo;
165	try	{
166	paymentInfo	=	paymentInfoQueryService.getPaymentInfoEntity(user.getEmail(),	requestDto.getPaymentInfoId());
167	if	(paymentInfo	==	null)	{
168	throw	new	PaymentInfoNotFoundException("결제	정보	ID:	"	+	requestDto.getPaymentInfoId()	+	"를	찾을	수	없습니다.");
169	}
170	}	catch	(PaymentException	e)	{
171	throw	e;	//	이미	PaymentException이면	그대로	전파
172	}	catch	(Exception	e)	{
173	throw	new	PaymentInfoNotFoundException("결제	정보	조회	중	오류가	발생했습니다.",	e);
174	}
175
176	//	2.	결제	요청	생성
177	Map<String,	Object>	response;
178	try	{
179	response	=	portOneApiClient.processCardPayment(paymentInfo,	requestDto.getPaidAmount());
180	}	catch	(PaymentException	e)	{
181	throw	e;	//	이미	PaymentException이면	그대로	전파
182	}	catch	(Exception	e)	{
183	throw	new	PaymentApiException("카드	결제	요청	중	오류가	발생했습니다:	"	+	e.getMessage());
184	}
185
186	//	3.	CardPayment	생성	및	저장
187	CardPayment	cardPayment	=	CardPayment.builder()
188	.cardNumber(paymentInfo.getCardNumber())
189	.cardPassword(paymentInfo.getCardPassword())
190	.cardExpiration(paymentInfo.getExpirationDate())
191	.birthDate(paymentInfo.getBirthDate())
192	.cardType((String)	response.get("card_name"))
193	.paidAmount(requestDto.getPaidAmount())
194	.impUid((String)	response.get("imp_uid"))
195	.receiptUrl((String)	response.get("receipt_url"))
196	.pgProvider((String)	response.get("pg_provider"))
197	.pgTid((String)	response.get("pg_tid"))
198	.build();
199
200	cardPayment.assignOrder(order);
201	cardPayment.assignUser(user);
202
203	if	("success".equals(response.get("status")))	{
204	cardPayment.updateStatus(PaymentStatus.PAID);
205	cardPayment.updateSuccessStatus(true);	//	결제	성공
206	}
207
208	CardPayment	savedPayment	=	(CardPayment)	paymentRepository.save(cardPayment);
209	log.info("카드	결제	처리	완료:	주문ID={},	결제ID={},	상태={}",
210	order.getId(),	savedPayment.getId(),	savedPayment.getStatus());
211
212	//	처리	시간	로깅
213	Instant	end	=	Instant.now();
214	Duration	duration	=	Duration.between(start,	end);
215	log.debug("카드	결제	처리	시간:	{}ms",	duration.toMillis());
216
217	return	savedPayment;
218	}	catch	(PaymentException	e)	{
219	throw	e;	//	이미	PaymentException이면	그대로	전파
220	}	catch	(Exception	e)	{
221	log.error("카드	결제	처리	중	예상치	못한	오류	발생:	주문ID={},	오류={}",
222	order.getId(),	e.getMessage(),	e);
223	throw	new	PaymentProcessingException("카드	결제	처리	중	오류가	발생했습니다:	"	+	e.getMessage());
224	}
225	}
